  },
  "publishConfig": {
    "access": "public"
  },
  "main": "index.js",
  "exports": {
    ".": "./index.js"
  },
  "bin": {
    "opencode-openchamber-mobile-bridge": "bin/opencode-openchamber-mobile-bridge.mjs"
